  /// Разбор путей из генератора: только абсолютные M, C и Z.
  static Path _paths(List<String> ds) {
    final p = Path();
    for (final d in ds) {
      final t = RegExp(r'[MCZ]|-?[0-9.]+').allMatches(d).map((m) => m.group(0)!).toList();
      var i = 0;
      double n() => double.parse(t[i++]);
      while (i < t.length) {
        switch (t[i++]) {
          case 'M':
            p.moveTo(n(), n());
          case 'C':
            p.cubicTo(n(), n(), n(), n(), n(), n());
          case 'Z':
            p.close();
        }
      }
    }
    return p;
  }
